def kategorien_zu_ordnern(apps, schema_editor):
    """Übernimmt bestehende Daten: Kategorien der Gewichtungsvorlage werden zu obersten Ordnern."""
    Unterricht = apps.get_model("noten", "Unterricht")
    Bewertungsordner = apps.get_model("noten", "Bewertungsordner")
    Leistungsnachweis = apps.get_model("noten", "Leistungsnachweis")
    for u in Unterricht.objects.all():
        ordner_je_kategorie = {}
        if u.gewichtung_id:
            for i, kat in enumerate(u.gewichtung.kategorien.all().order_by("-anteil", "name")):
                ordner_je_kategorie[kat.pk] = Bewertungsordner.objects.create(
                    unterricht=u, name=kat.name, gewicht=kat.anteil, reihenfolge=(i + 1) * 10
                )
        for ln in Leistungsnachweis.objects.filter(unterricht=u):
            ordner = ordner_je_kategorie.get(ln.kategorie_id)
            if ordner is None:
                ordner, _ = Bewertungsordner.objects.get_or_create(
                    unterricht=u, eltern=None, name=ln.kategorie.name, defaults={"gewicht": ln.kategorie.anteil}
                )
                ordner_je_kategorie[ln.kategorie_id] = ordner
            ln.ordner = ordner
            ln.save(update_fields=["ordner"])


